        if(!scope.equals("ui")){click("播放");until(()->playerStarted(),"VOD playback missing");SystemClock.sleep(1500);ui(()->{call(activity,"showPlayerControls",new Class[]{});((View)field(activity,"playerToggle")).requestFocus();});key(KeyEvent.KEYCODE_DPAD_CENTER);until(()->read(()->!((android.media.MediaPlayer)field(activity,"player")).isPlaying()),"pause failed");long before=read(()->(long)((android.media.MediaPlayer)field(activity,"player")).getCurrentPosition());key(KeyEvent.KEYCODE_DPAD_RIGHT);until(()->read(()->((android.media.MediaPlayer)field(activity,"player")).getCurrentPosition()>before+5000),"default right seek failed");check(read(()->!((android.media.MediaPlayer)field(activity,"player")).isPlaying()),"default right seek preserves pause");key(KeyEvent.KEYCODE_DPAD_LEFT);until(()->read(()->((android.media.MediaPlayer)field(activity,"player")).getCurrentPosition()<before+3000),"default left seek failed");check(read(()->!((android.media.MediaPlayer)field(activity,"player")).isPlaying()),"default left seek preserves pause");key(KeyEvent.KEYCODE_BACK);until(()->read(()->(text("播放")!=null||text("继续 · 正片")!=null)),"return to detail failed");}
